using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using Microsoft.Extensions.Hosting;using Mbb.Archive.BuildingBlocks.Application;
namespace Mbb.Archive.Modules.Archive.Infrastructure.Persistence;
internal sealed class ArchiveOutboxPublisher:BackgroundService{private readonly IServiceScopeFactory _scopes;private readonly IIntegrationEventPublisher _publisher;private readonly TimeProvider _time;private readonly string _worker=$"archive:{Environment.MachineName}:{Guid.CreateVersion7():N}";public ArchiveOutboxPublisher(IServiceScopeFactory scopes,IIntegrationEventPublisher publisher,TimeProvider time){_scopes=scopes;_publisher=publisher;_time=time;}protected override async Task ExecuteAsync(CancellationToken ct){while(!ct.IsCancellationRequested){try{var batch=await Claim(ct);foreach(var x in batch)await Publish(x,ct);if(batch.Count==0)await Task.Delay(1000,ct);}catch(OperationCanceledException)when(ct.IsCancellationRequested){break;}catch{await Task.Delay(1000,ct);}}}private async Task<IReadOnlyList<E>> Claim(CancellationToken ct){await using var s=_scopes.CreateAsyncScope();var db=s.ServiceProvider.GetRequiredService<ArchiveDbContext>();var now=_time.GetUtcNow();await using var tx=await db.Database.BeginTransactionAsync(ct);var rows=await db.Outbox.FromSqlInterpolated($"""SELECT * FROM archive.outbox_messages WHERE processed_at IS NULL AND dead_lettered_at IS NULL AND next_attempt_at <= {now} AND (locked_until IS NULL OR locked_until < {now}) ORDER BY occurred_at LIMIT 50 FOR UPDATE SKIP LOCKED""").ToListAsync(ct);foreach(var r in rows)r.Lease(_worker,now.AddSeconds(120));await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return rows.Select(x=>new E(x.Id,x.EventName,x.Payload,x.OccurredAt,x.AttemptCount)).ToArray();}private async Task Publish(E e,CancellationToken ct){try{await _publisher.PublishAsync(e.Id,e.Name,e.Payload,e.At,ct);await using var s=_scopes.CreateAsyncScope();var db=s.ServiceProvider.GetRequiredService<ArchiveDbContext>();var row=await db.Outbox.SingleAsync(x=>x.Id==e.Id,ct);row.Published(_worker,_time.GetUtcNow());await db.SaveChangesAsync(ct);}catch(Exception ex){await using var s=_scopes.CreateAsyncScope();var db=s.ServiceProvider.GetRequiredService<ArchiveDbContext>();var row=await db.Outbox.SingleAsync(x=>x.Id==e.Id,ct);var n=_time.GetUtcNow();row.Failed(_worker,ex.Message,n,n.AddSeconds(Math.Min(Math.Pow(2,e.Attempt+1),300)),10);await db.SaveChangesAsync(ct);}}private sealed record E(Guid Id,string Name,string Payload,DateTimeOffset At,int Attempt);}
